const items = $input.all();
const output = [];

for (const item of items) {
  try {
    // 1. Safely handle both object and stringified JSON payloads from Meta
    let rawBody = item.json.body || item.json;
    if (typeof rawBody === 'string') {
      try { rawBody = JSON.parse(rawBody); } catch (e) {}
    }

    const entry = rawBody?.entry?.[0];
    const messaging = entry?.messaging?.[0];

    // 2. Drop if there is no messaging payload
    if (!messaging) {
      continue;
    }

    // 3. CRITICAL: Drop bot echoes (messages sent by your own page) to prevent loops
    if (messaging.message?.is_echo === true) {
      continue;
    }

    // 4. Extract senderId, message text, and unique message ID (mid)
    const senderId = messaging?.sender?.id;
    const messageText = messaging?.message?.text;
    const messageId = messaging?.message?.mid;

    if (!senderId || !messageText || !messageId) {
      continue;
    }

    // 5. Output valid user text messages along with messageId for deduplication
    output.push({
      json: {
        senderId: senderId,
        messageId: messageId,
        message: messageText,
        receivedAt: new Date().toISOString()
      }
    });
  } catch (err) {
    // Silently skip system pings or malformed data to keep executions clean
    continue;
  }
}

return output;

// Grab the sender ID and message ID from your earlier preprocessing step
const senderId = $('Code in JavaScript').first().json.senderId;
const messageId = $('Code in JavaScript').first().json.messageId;

// Grab the raw text from the AI Agent, strip bracketed tags, and remove all markdown asterisks and underscores
const rawAiText = $('AI Agent').first().json.output;
const aiText = rawAiText.replace(/\[.*?\]/g, '').replace(/[*_]/g, '').trim();

// Return the cleaned JSON payload including messageId for the deduplication node
return [{
  json: {
    messageId: messageId,
    recipient: { id: senderId },
    message: { text: aiText }
  }
}];

