// Grab the incoming customer message directly from the Webhook node
const message = $('Webhook').item.json.body.entry[0].messaging[0].message.text.toLowerCase();

// Define comprehensive keywords for refunds, complaints, product damage, and support escalation
const supportKeywords = [
  'money back', 'refund', 'return', 'cancel', 
  'teared', 'torn', 'damaged', 'broken', 'defective', 'ruined', 
  'bullshit', 'scam', 'fraud', 'complaint', 'terrible', 'horrible',
  'support', 'help', 'issue', 'problem', 'agent', 'human', 'speak to someone'
];

// Check if the customer message contains any trigger phrase
const needsSupport = supportKeywords.some(keyword => message.includes(keyword));

if (needsSupport) {
  return [{ 
    json: {
      originalMessage: $('Webhook').item.json.body.entry[0].messaging[0].message.text,
      escalationReason: "Customer requested a refund, reported product damage, or used complaint keywords.",
      timestamp: new Date().toISOString()
    } 
  }];
} else {
  return [];
}
